    (26, 'elllo-b2-03-was-able-to', 'Was able to', 'Human-recorded ELLLO conversations for Was able to.', 'B2', 'ELLLO Grammar', 6, 3, TRUE),
    (27, 'elllo-b2-04-was-going-to', 'Was going to', 'Human-recorded ELLLO conversations for Was going to.', 'B2', 'ELLLO Grammar', 6, 4, TRUE),
