INSERT INTO lesson_sentences (id, lesson_id, position_index, transcript, audio_url, speech_rate) VALUES
    (25, 9, 1, 'Hello! Are you a new student? Yes, I am. Today is my first day. Well, welcome. My name is Tony. Hi, Tony. I’m Beth. Are you new in town? Yes, I’m from New York. Wow! The Big City! Are you from around here? Yes, I am. That is so cool. Well, it is nice to meet you. Nice to meet you, too.', '/audio/elllo/A1/A1-01-Be-Verbs-Introductions/conversation-1-A1-01-1-Be-Verbs-First-Day.mp3', 1.0),
    (26, 9, 2, 'Hey Beth, how is your first day? It is really good. This school is great! How are your classes? They are fun! My teachers are so nice. Who are your teachers? My English teacher is Mr. Wong. Oh, he is really nice. Yes, he is. My Spanish teacher is Mrs. Garcia. Oh, she is really nice, too. Yes, her class is a lot of fun!', '/audio/elllo/A1/A1-01-Be-Verbs-Introductions/conversation-2-A1-01-2-Be-Verbs-Teachers.mp3', 1.0),
    (27, 9, 3, 'What is your favorite class? Spanish. I love it. My Spanish is not very good, though. I am just a beginner. Well, Spanish is my first language. My name is Tony, short for Antonio. Really! That is so cool. Yeah, my dad is from Mexico, and my mom is from Costa Rica. Wow! You are so lucky. Yeah, Spanish is easy for me, so I can help you if you like. I’d like that. Thank you!', '/audio/elllo/A1/A1-01-Be-Verbs-Introductions/conversation-3-A1-01-3-Be-Verbs-Classes.mp3', 1.0),
    (28, 9, 4, 'Tony, where is the computer lab? It’s just down the hall. My Spanish class is there tomorrow. Oh, when is the class? It’s at 6, after school. Why isn’t the class online? It is, but I’m still new in town, so I don’t have internet at home yet. Oh, I see. Well, good luck with the class. Thanks. I’m excited for it. I think online classes are fun! I think so, too.', '/audio/elllo/A1/A1-01-Be-Verbs-Introductions/conversation-4-A1-01-4-Be-Verbs-Lab.mp3', 1.0),
    (29, 10, 1, 'Are you hot? Yes, I am very hot. Is the air-conditioning on? No, it is off. Can I turn it on? Yes, please do. And can you turn on the radio, too? Of course. Is jazz music alright? Yes, I love jazz music.', '/audio/elllo/A1/A1-02-Be-Yes-No-Questions/conversation-1-A1-02-1-Be-Yes-No-Questions-Hot.mp3', 1.0),
    (30, 10, 2, 'Is your house big? Yes, it is pretty big. Is it new? No, it is very old. Is it nice? Not really. It is cold in winter. Oh, no! That’s not good.', '/audio/elllo/A1/A1-02-Be-Yes-No-Questions/conversation-2-A1-02-2-Be-Yes-No-Questions-House.mp3', 1.0),
    (31, 10, 3, 'I like your shoes. Are they new? Yes, they are. Are they expensive? No, they are very cheap. Are they comfortable? Yes, they are very comfortable. Are they from the discount shoe shop? Yes! How did you guess?', '/audio/elllo/A1/A1-02-Be-Yes-No-Questions/conversation-3-A1-02-3-Be-Yes-No-Questions-Clothes.mp3', 1.0),
    (32, 10, 4, 'Are you hungry? Yes, I am very hungry. Do you want pizza? Yes, let''s get some. Is the pizza shop still open? Yes, it is open until 10. What time is it now? Eight. It’s open for two more hours. Great! I’m starving.', '/audio/elllo/A1/A1-02-Be-Yes-No-Questions/conversation-4-A1-02-4-Be-Yes-No-Questions-Hungry.mp3', 1.0),
    (33, 11, 1, 'So, what foods do you like? I like ice cream, and pizza, and apples. Ooh, I like those foods, too. What foods do you like? I like fish, vegetables, and bananas. Together? No, not together!', '/audio/elllo/A1/A1-03-Likes-Food/conversation-1-A1-03-1-Likes-Food.mp3', 1.0),
    (34, 11, 2, 'What drinks do you like? I like tea, and I like juice. Ooh, hot tea or cold tea? Both. What about you? I like coffee and hot chocolate. Ooh, I like both, too!', '/audio/elllo/A1/A1-03-Likes-Food/conversation-2-A1-03-2-Likes-Drinks.mp3', 1.0),
    (35, 11, 3, 'What desserts do you like? I really like ice cream. Oh! What flavor do you like? Hmm, I like strawberry. I like vanilla, too. Nice! I like cake, and I like pie. What kind of pie? I really like apple pie with ice cream. Yum!', '/audio/elllo/A1/A1-03-Likes-Food/conversation-3-A1-03-3-Likes-Desserts.mp3', 1.0),
    (36, 11, 4, 'What snacks do you like? I like to eat fruit. Oh yeah? And what fruits do you like? I like apples and oranges. And you? I like strawberries and watermelon. Do you like to eat cookies? Of course! I love chocolate chip cookies. Me, too!', '/audio/elllo/A1/A1-03-Likes-Food/conversation-4-A1-03-4-Likes-Snacks.mp3', 1.0),
    (37, 12, 1, 'What do you do in the morning? I wake up. I take a shower. I get dressed, and I eat breakfast. Oh! When do you get up? I get up at 6. Wow! That’s early. I know! I like mornings, though.', '/audio/elllo/A1/A1-04-Verbs/conversation-1-A1-04-1-Verbs-Morning.mp3', 1.0),
    (38, 12, 2, 'What do you do during the day? Well, I go to school. I teach students. Ooh! What do you teach? I teach math. What do you do? I work at a bike shop. Really? What do you do at the shop? I fix and sell bikes. Sounds fun.', '/audio/elllo/A1/A1-04-Verbs/conversation-2-A1-04-2-Verbs-Day.mp3', 1.0),
    (39, 12, 3, 'What do you do at lunch? I eat with my friends. And you? I eat in the park. That’s nice. Yeah, I like to read on my lunch break. Ooh, what do you read? I read about history. Interesting.', '/audio/elllo/A1/A1-04-Verbs/conversation-3-A1-04-3-Verbs-Lunch.mp3', 1.0),
    (40, 12, 4, 'What do you do on the weekend? I play sports at the park. How about you? I study at the library. Oh, right! You love books. Yeah. So, what sports do you play? I play soccer with my friends. Sounds fun. It is!', '/audio/elllo/A1/A1-04-Verbs/conversation-4-A1-04-4-Verbs-Weekend.mp3', 1.0),
    (41, 13, 1, 'Do you play sports? Yes, I do. I really love basketball. Do you play on a team? Yes, but we do not play in winter. Oh, do you play in summer? Yes, we play in spring and summer. Do you play at the gym in town? No, we play at a high school.', '/audio/elllo/A1/A1-05-Verb-Yes-No-Questions/conversation-1-A1-05-1-Verb-Yes-No-Questions-Sports.mp3', 1.0),
    (42, 13, 2, 'Do you have any pets? Yes, I have a cat. What about you? Do you? I don''t have a cat, but I have a dog. Nice! Do you have a big yard? Yes, I have a big yard, so it is perfect for my dog. Yeah, I don''t have a yard, so I can only have a cat.', '/audio/elllo/A1/A1-05-Verb-Yes-No-Questions/conversation-2-A1-05-2-Verb-Yes-No-Questions-Pets.mp3', 1.0),
    (43, 13, 3, 'Do you cook much? Yes, I cook all the time. Do you cook? No, I don''t like to cook very much. Oh, so do you buy your dinner? Yes, I buy it at the supermarket. Do you buy dinner every night? Yes, I never cook. Wow! That is expensive.', '/audio/elllo/A1/A1-05-Verb-Yes-No-Questions/conversation-3-A1-05-3-Verb-Yes-No-Questions-Cooking.mp3', 1.0),
    (44, 13, 4, 'Do you live downtown? Yes, I live near the train station. Do you take the train to work? Yes, most days. What about you? I live far away, so I drive to work. Do you have a nice car? No, my car is old, but I like it.', '/audio/elllo/A1/A1-05-Verb-Yes-No-Questions/conversation-4-A1-05-4-Verb-Yes-No-Questions-Housing.mp3', 1.0),
    (45, 14, 1, 'What do you do? I work at a tech company. Oh, what do you do there? I design software. Do you like your job? Yeah, I enjoy it. Where is your office? I work at the new office downtown. Nice. How do you get to work? I take the bus. I don’t have a car. Same here!', '/audio/elllo/A2/A2-01-Present-Simple/conversation-1-A2-01-1-Present-Simple-Job.mp3', 1.0),
    (46, 14, 2, 'Do you belong to a gym? Yes, I go to the gym near my house. What do you do at the gym? How do you exercise? On Monday and Tuesday I do yoga. The gym has a pool, so I sometimes swim. Oh, I do yoga too! I do it at home though. I watch videos online. Oh, you don’t belong to a gym? No, I don’t like gyms. For exercise, I jog in the park, or play soccer with friends. Oh, that works. I love running in the park. Cool! Let’s jog together sometime. I’d like that!', '/audio/elllo/A2/A2-01-Present-Simple/conversation-2-A2-01-2-Present-Simple-Gym.mp3', 1.0),
    (47, 14, 3, 'What do your parents do? They both work in sales. Oh, what do they sell? They sell houses. They have a real estate company. That’s a difficult job. It is. They work long hours, but they like it. What about your parents? They’re professors. They teach at the university. Oh, what do they teach? They both teach business.', '/audio/elllo/A2/A2-01-Present-Simple/conversation-3-A2-01-3-Present-Simple-Parents.mp3', 1.0),
    (48, 14, 4, 'Where do you live? I live near the river. Oh, I love that area. Do you live in a house or an apartment? I live in a house. Nice. Do you live alone, or with family? I live with my parents. I don’t pay rent, so I save money. Do you like it there? Yes, I do, but my house is old. What about you? I live in a small apartment downtown near the station. Do you live alone? Yes, I do, but I want a roommate. Really? How much is the rent?', '/audio/elllo/A2/A2-01-Present-Simple/conversation-4-A2-01-4-Present-Simple-House.mp3', 1.0),
    (49, 15, 1, 'What does your dad do? He works in construction. Oh, what does he do? He builds houses. Nice, what about your mother? She works for the city. What does she do? She is a clerk. She helps people at City Hall.', '/audio/elllo/A2/A2-02-Present-Simple-3rd-Person/conversation-1-A2-02-1-Present-Simple-3rd-Person-Dad.mp3', 1.0),
    (50, 15, 2, 'Where does your sister live? She lives in the countryside. Oh? What does she do? She has a farm and she raises animals. What animals does she have on her farm? She has horses, cows and sheep. Wow, that’s so cool! Yeah, she also grows her own food. What food does she grow? She grows corn, beans, tomatoes and potatoes.', '/audio/elllo/A2/A2-02-Present-Simple-3rd-Person/conversation-2-A2-02-2-Present-Simple-3rd-Person-Sister.mp3', 1.0),
    (51, 15, 3, 'How does your mother stay so fit? She works out alot. It shows. She looks great! She also watches what she eats. Does she follow a special diet? Yes. She doesn’t eat sweets and she doesn’t drink soda. What about your dad? Oh, he never works out. He also does yoga. Does he follow a healthy diet too? Not really. He eats sweets, and he loves ice cream.', '/audio/elllo/A2/A2-02-Present-Simple-3rd-Person/conversation-3-A2-02-3-Present-Simple-3rd-Person-Mother.mp3', 1.0),
    (52, 15, 4, 'How do you study language? I use an app on my phone. What does the app do? It teaches vocabulary. It has over 20 languages. Really? What languages does it teach? It teaches many languages. French, Spanish, Japanese, and lots more. How does it work? Just type in a word in English, and it shows the translation. That sounds pretty cool. It is. It also pronounces the words, and gives example sentences. Nice! I want to try it.', '/audio/elllo/A2/A2-02-Present-Simple-3rd-Person/conversation-4-A2-04-4-Will-Game.mp3', 1.0),
    (53, 16, 1, 'What are you doing? I’m writing a report. What are you writing about? I’m writing about Bitcoin. Oh, that sounds interesting. It is! I’m learning a lot. Where are you getting your information? Wikipedia and Chat GPT. That works, I guess.', '/audio/elllo/A2/A2-03-Present-Continuous/conversation-1-A2-03-1-Present-Continuous-Report.mp3', 1.0),
    (54, 16, 2, 'Where is mom? She’s in the kitchen. She’s cooking dinner. Where’s dad? He’s outside. He’s sitting on the porch. He’s waiting for dinner. What’s he doing outside? He’s listening to news on the radio. Why doesn’t he watch the news on TV? The TV isn’t working. Oh, that’s too bad. Well, it is a nice day to be outside.', '/audio/elllo/A2/A2-03-Present-Continuous/conversation-2-A2-03-2-Present-Continuous-Family.mp3', 1.0),
    (55, 16, 3, 'Hey, what a surprise! What are you doing here? I’m waiting for my friend. I’m meeting him for lunch. Nice! Where are you going? We’re going to the new Italian restaurant. Oh, I hear it’s really good. What about you? What are you doing? Are you shopping? Yeah. I’m picking up a few things, and then I’m going to the gym. Well, have a good workout. Thanks! Enjoy your meal. Thanks!', '/audio/elllo/A2/A2-03-Present-Continuous/conversation-3-A2-03-3-Present-Continuous-Encounter.mp3', 1.0),
    (56, 16, 4, 'What’s happening outside? I think a car hit a man on a bike. Oh no! Is he hurt? I’m not sure. He’s lying on the ground. Oh no. Is it serious? No, he is getting up now. Well, that’s good. He looks OK. He’s smiling and talking now. Oh, good! That’s good news.', '/audio/elllo/A2/A2-03-Present-Continuous/conversation-4-A2-03-4-Present-Continuous-Accident.mp3', 1.0),
    (57, 17, 1, 'How is your French class? Good, but it will finish next week. Oh, will you take the next course? No, I can’t. I won’t have time. I’m surprised to hear that. You love that class. I do, but I will start a new job next week. The class and my job will be at the same time. That''s too bad! It’s OK. I will still study on my own. That’s the spirit!', '/audio/elllo/A2/A2-04-Will/conversation-1-A2-04-1-Will-Class.mp3', 1.0),
    (58, 17, 2, 'The company picnic is the 18th. Will you be there? Yes, I think I’ll go. What time does it start? It will begin at 12 and will go until 5. OK, I’ll try to make it. Will your wife be there? No, she won’t be there this year. She has to work. Oh, that’s too bad. My husband won’t come, either. He''s out of town. So, will you come alone? No, I will bring my kids. They love the free food. My kids too. I am sure they will eat a lot! Mine, too.', '/audio/elllo/A2/A2-04-Will/conversation-2-A2-04-2-Will-Picnic.mp3', 1.0),
    (59, 17, 3, 'Where will you go for the summer break? I will go to the beach with my family. That sounds fun. How long will you be there? We won''t stay long, maybe two or three days. Nice. Where will you stay? We will stay at the new hotel. It just opened! Nice choice. I hear it’s really beautiful.', '/audio/elllo/A2/A2-04-Will/conversation-3-A2-04-3-Will-Summer.mp3', 1.0),
    (60, 17, 4, 'When’s our next soccer game? It’s next Tuesday. Who will we play? We will play Mary’s team, the Lions. Great. Will everyone be there? Matt won’t be there, but everyone else will. Oh,that’s too bad.Well, we’ll miss him. Where will we play? We’ll play at the new soccer field by City Café. Oh, I love that field. We always win there. We’ll see! Don’t get too confident! Don’t worry! I won’t! We’ll also go out for pizza after the game. That sounds fun. It should be! Especially if we win!', '/audio/elllo/A2/A2-04-Will/conversation-4-A2-04-4-Will-Game.mp3', 1.0),
    (61, 18, 1, 'What are you going to do tonight? I’m just going to stay home. What about you? I’m going to the movies with Karen. Oh? What are you going to see? We’re going to see the new Marvel movie. Do you want to come? No, I’ll pass. But thanks for asking. Are you sure? It’s going to be fun. No thanks. I’m just going to take it easy tonight. OK, maybe next time.', '/audio/elllo/A2/A2-05-Going-To/conversation-1-A2-05-1-Going-To-Tonight.mp3', 1.0),
    (62, 18, 2, 'So, what are you going to do this summer? Nothing. I’m going to visit my grandparents. We’re going to go camping. That sounds fun. Where are you going? We’re going to stay at a campground near their house. Oh, are you going to stay in a cabin? No, we’re going to camp by the lake. It’s really beautiful there. Well, I hope you have a nice trip. Thanks. It’s going to be a lot of fun.', '/audio/elllo/A2/A2-05-Going-To/conversation-2-A2-05-2-Going-To-Camping.mp3', 1.0),
    (63, 18, 3, 'We’re going to a barbecue tonight. Care to join us? Oh, I love barbecue! What are you going to cook? We are going to grill either chicken or steak. That sounds delicious, I’d love to go. When should I come over? We’re not going to start until 7, so around then. Great. Should I bring anything? David is going to bring salad, so maybe you can bring dessert. Great! How many people are coming? There’s going to be about 10 people. OK, I’ll bring some ice cream. Perfect. Everyone will love that.', '/audio/elllo/A2/A2-05-Going-To/conversation-3-A2-05-3-Going-To-BBQ.mp3', 1.0),
    (64, 18, 4, 'Where are you going for vacation? I’m going to Hawaii. Lucky you! When are you going? Next week, on the 5th. How long are you going to be there? About a week. 8 days. Where are you going to stay? We’re going to stay at a resort, on the beach. Are you going to take your kids? No, I’m just going with my husband. My kids are going to stay with their grandparents. Well, have a nice trip! Thanks, I’m excited about it!', '/audio/elllo/A2/A2-05-Going-To/conversation-4-A2-05-4-Going-To-Vacation.mp3', 1.0),
    (65, 19, 1, 'Do you like sports? No, but I do like golf. Golf? You don’t like golf? I did like it when I was younger, but not now. Oh, I love it. Why don''t you like it anymore? It''s just too expensive. True. It does cost a lot to play.', '/audio/elllo/B1/B1-01-Do-Emphasis/conversation-1-B1-01-1-Do-Emphasis-Sports.mp3', 1.0),
    (66, 19, 2, 'Do you cook much? I do cook a lot. What do you cook? Just easy stuff like pasta dishes. And you? I don’t cook much. I do cook breakfast, though. Really, I never cook breakfast. My husband does make me pancakes sometimes, though.', '/audio/elllo/B1/B1-01-Do-Emphasis/conversation-2-B1-01-2-Do-Emphasis-Cooking.mp3', 1.0),
    (67, 19, 3, 'Do you watch much TV? I do watch a lot of TV. What do you watch? I watch dramas. And you? I rarely watch TV. I do watch the news sometimes, though. How depressing! The news always makes me feel sad. Yeah, it does get depressing sometimes.', '/audio/elllo/B1/B1-01-Do-Emphasis/conversation-3-B1-01-3-Do-Emphasis-TV.mp3', 1.0),
    (68, 19, 4, 'Do you have any kids? I don’t. And you? I do have kids, but they are all grown now. Do they live near you? They did live near me, but they moved. Oh, I’m sorry to hear that. Yeah, me too. They do still visit a lot, though. Did you see them over the holidays? I did see them. We had a really nice time together.', '/audio/elllo/B1/B1-01-Do-Emphasis/conversation-4-B1-01-4-Do-Emphasis-Kids.mp3', 1.0),
    (69, 20, 1, 'Can you help me do this? Sure, what are trying to do? I’m trying to put up this tent. Oh, it’s easy. Let me show you what to do. Wow! That was so easy for you. Yeah, I was in the army. We do this all the time.', '/audio/elllo/B1/B1-02-Causative-Verbs/conversation-1-B1-02-1-Causative-Verbs-Tent.mp3', 1.0),
    (70, 20, 2, 'Why are you home so late? My boss made me stay late today. Why did she do that? I had to help her write a letter in French. Huh! That was nice of you. Well, she made me do it. She’s the boss.', '/audio/elllo/B1/B1-02-Causative-Verbs/conversation-2-B1-02-2-Causative-Verbs-Late.mp3', 1.0),
    (71, 20, 3, 'Did you get a new car? No, my friend is letting me use his. What happened to your car? It is getting repairs. Lucky you! This is a nice car. Well, he made me promise I’d be careful with it.', '/audio/elllo/B1/B1-02-Causative-Verbs/conversation-3-B1-02-3-Causative-Verbs-Car.mp3', 1.0),
    (72, 20, 4, 'Your mom is so nice! Yeah, she is now, but she was really strict when I was younger. Really? How so? Well, for one, she never let me watch TV or eat sugar. Wow! That is strict! And she made me study at least four hours a day, even if I did not have homework. Wow! That sounds like tough love.', '/audio/elllo/B1/B1-02-Causative-Verbs/conversation-4-B1-02-4-Causative-Verbs-Mom.mp3', 1.0),
    (73, 21, 1, 'Do you play sports? I used to play sports in high school. Yeah, I used to play, too. Why did you stop? No time, I guess. Yeah, I used to have so much free time. Me too! I miss those days. What sports did you play? Baseball and basketball. I used to be pretty good, not anymore, though. Yeah, we all get older.', '/audio/elllo/B1/B1-03-UsedTo/conversation-1-B1-03-1-Used-To-Sports.mp3', 1.0),
    (74, 21, 2, 'Do you speak any foreign languages? I speak French a little. I used to use it all the time, but not anymore. Really? Why is that? Well, I used to work for a French company, and then I changed jobs. Oh, really? I didn’t know that. Yeah, it was a lot of fun. I used to go to France once a year for work. Lucky you! I love France. Yeah, France is a lot of fun.', '/audio/elllo/B1/B1-03-UsedTo/conversation-2-B1-03-2-Used-To-Language.mp3', 1.0),
    (75, 21, 3, 'Are you coming to the party? No, I have to work. Work! What happened? You used to never miss a party! True, but I also didn’t use to have a stressful job. True, you used to be poor, but you were fun! Yep! I used to be fun!', '/audio/elllo/B1/B1-03-UsedTo/conversation-3-B1-03-3-Used-To-Party.mp3', 1.0),
    (76, 21, 4, 'Hey, you used to have a Spanish co-worker, right? Yeah, Maria, but she moved. Really? That’s too bad. I liked her. She used to always make me laugh. I know. We used to have such fun together. She was so nice. She used to give me sweets when I visited your office. Yeah, she loved baking. She used to bring cookies and cupcakes to the office every Friday. Sounds like you miss her. I do! We all do.', '/audio/elllo/B1/B1-03-UsedTo/conversation-4-B1-03-4-Used-To-CoWorker.mp3', 1.0),
    (77, 22, 1, 'What was it like growing up on a farm? It was the best. I used to have so much fun. Really? What would you do? I would ride horses, play with my dog, tend to animals and just have fun! Sounds fun! It was. Every day I would get up early and I would be outside all day. I wouldn’t go inside until dark. Sounds like you had a great childhood. It was.', '/audio/elllo/B1/B1-04-Would-PastTense/conversation-1-B1-04-1-Would-PastTense-Farm.mp3', 1.0),
    (78, 22, 2, 'What was it like growing up in the city? It was fun. I have many good memories. Yeah, such as? Well, my friends and I used to hang out downtown. We would sit on the sidewalk and watch the world go by. It was so fun. Sometimes, we’d get in trouble, though. Really, what would you do? Well, we would be loud or naughty. Kids’ stuff. Nothing serious, though. Yeah, sounds familiar.', '/audio/elllo/B1/B1-04-Would-PastTense/conversation-2-B1-04-2-Would-PastTense-City.mp3', 1.0),
    (79, 22, 3, 'What was life like in the army? It was good, but it was very hard. Really? How so? Well, we were always busy. Every day we would get up really early. Then, we would march for ten miles. After that, we would do more training. What would you do in the afternoon? More training. Usually, we wouldn’t stop training until late. That is so tough. How much sleep did you get? Not much. We would usually get about six hours a night. It wasn’t enough, though. Do you miss it? Yes, sometimes.', '/audio/elllo/B1/B1-04-Would-PastTense/conversation-3-B1-04-3-Would-PastTense-Army.mp3', 1.0),
    (80, 23, 1, 'You don’t look so good. Are you sick? Yes, I think I’m coming down with a cold. Well, maybe you should go home then. But I really need to work. No, no, no! You should go home and get some rest. OK. I guess I can work from home anyway. No, you shouldn’t work. You should stay in bed. OK. I will do that. Thanks for your advice. No problem. I hope you feel better soon.', '/audio/elllo/B1/B1-05-Should/conversation-1-B1-05-1-Should-Sick.mp3', 1.0),
    (81, 23, 2, 'So, how long have you been feeling ill? For about three days. Well, it looks like there’s a flu bug going around. OK. Is that serious? No, it is a minor illness, but you should not be around people as it can spread. OK. What should I do to get better? Just get lots of rest and drink lots of water. I will give you some medicine to make you feel better. OK. Thank you doctor. If you start to feel worse after a few days, you should call me immediately. OK. I’ll do that. Thank you. You’re welcome. You should feel better in a few days.', '/audio/elllo/B1/B1-05-Should/conversation-2-B1-05-2-Should-Doctor.mp3', 1.0),
    (82, 23, 3, 'What’s the best way to learn Spanish? Well, first you should learn new words every day. OK. That’s easy. What do you recommend? I would download a vocab app. I would try to learn ten words a day. Only ten words? I think I can learn 50 words a day. No, you shouldn’t do that because you won’t remember them. You shouldn’t try to do too much at one time. OK. I will follow your advice. Thank you.', '/audio/elllo/B1/B1-05-Should/conversation-3-B1-05-3-Should-Spanish.mp3', 1.0),
    (83, 23, 4, 'Hello, Mrs. Wilson. Thanks for your advice on learning Spanish vocabulary. Your tips worked. Do you have any more ways to learn Spanish? Well, you should try to use the words you learn by keeping a journal and trying to use them. That sounds too difficult. I can’t write anything yet. Well, at first you can just draw pictures of new words, like verbs and nouns. Oh, I like that idea. I’ll give that a try. Oh, and you should use spanishlistening.org. It’s a great way to learn Spanish. Sounds cool! Is it free? Yes, it’s free! There are 100s of listening lessons to choose from. Cool. I’ll check it out. Thanks.', '/audio/elllo/B1/B1-05-Should/conversation-4-B1-05-4-Should-Spanish.mp3', 1.0),
    (84, 24, 1, 'How is the new Thai restaurant? It’s great. All the food is cooked with organic ingredients. That sounds great. How late is it open? Well, food is served until 11, but the bar is open until midnight. I will have to check it out. You should. It’s worth the visit.', '/audio/elllo/B2/B2-01-Passive-Simple/conversation-1-B2-01-1-Passive-Present-Restaurant.mp3', 1.0),
    (85, 24, 2, 'Are you still playing basketball tonight? No, the game is canceled. Oh, no, why is that? The rec hall is reserved for something. That’s too bad. Yeah, some band is scheduled to play there tonight.', '/audio/elllo/B2/B2-01-Passive-Simple/conversation-2-B2-01-2-Passive-Present-Basketball.mp3', 1.0),
    (86, 24, 3, 'Is the report done yet? It is almost done. When will it be finished? It should be done very soon. Well, as soon as it is finished, please get it to me. I will. The minute it’s finished, you’ll get it.', '/audio/elllo/B2/B2-01-Passive-Simple/conversation-3-B2-01-3-Passive-Present-Report.mp3', 1.0),
    (87, 24, 4, 'This chair is broken. Who broke it? I don’t know. It was broken when I got here. Should I throw it out? No, I’ll see if maintenance can fix it. Don’t bother. It is more trouble than it’s worth. You may be right.', '/audio/elllo/B2/B2-01-Passive-Simple/conversation-4-B2-01-4-Passive-Present-Chair.mp3', 1.0),
    (88, 25, 1, 'When was this subway built? It was built about 30 years ago. It still looks pretty new. Yes, it was remodeled last year. Well, they did a nice job. I’ll say.', '/audio/elllo/B2/B2-02-Past-Passive/conversation-1-B2-02-1-Past-Passive-Subway.mp3', 1.0),
    (89, 25, 2, 'What happened to the old stadium? It was torn down last year. Why did they tear it down? It was damaged by the hurricane three years ago. Oh, I remember that. Yeah, a lot of damage was done that night.', '/audio/elllo/B2/B2-02-Past-Passive/conversation-2-B2-02-2-Past-Passive-Stadium.mp3', 1.0),
    (90, 25, 3, 'Do you still go to that hotel by the lake? No, it was sold last year. Oh, was it replaced? No, it was closed and hasn’t been reopened. Oh, that’s too bad. Yeah, summer at the lake hasn’t been the same since.', '/audio/elllo/B2/B2-02-Past-Passive/conversation-3-B2-02-3-Past-Passive-Hotel.mp3', 1.0),
    (91, 25, 4, 'Do you still play golf? No, the course was shut down last year. Oh, that was such a beautiful course. What happened to it? It was converted to a park. Well, at least it was put to good use. Yeah, my kids love to go there now.', '/audio/elllo/B2/B2-02-Past-Passive/conversation-4-B2-02-4-Past-Passive-Golf.mp3', 1.0),
    (92, 26, 1, 'How did you do on the test? Not great. I wasn’t able to answer all the questions. I ran out of time. Same here. Some of the questions were really hard. Were you able to finish the essay section? Yeah, I was able to do that, at least. Me too, although I wasn’t able to write 300 words. Me neither! How many words did you write? I was only able to write about 200 words. Same! Well, fingers crossed we get a good grade. Yes, fingers crossed!', '/audio/elllo/B2/B2-03-Was-Able-To/conversation-1-B2-03-1-Was-Able-To-Test.mp3', 1.0),
    (93, 26, 2, 'So, how is the wedding planning coming along? Good, we have finalized most of the arrangements. Are you still having the wedding at the lake? No, we weren’t able to get the place we wanted. Oh, then where are you having it then? We are having it at a hotel in the countryside. Well, it sounds nice. Yeah, in the end, it worked out well. We were able to get a really good deal on the caterer, too. Oh, that’s great! I am glad to hear it.', '/audio/elllo/B2/B2-03-Was-Able-To/conversation-2-B2-03-2-Was-Able-To-Wedding.mp3', 1.0),
    (94, 26, 3, 'I am sorry I wasn’t able to attend your birthday party on Saturday. Yeah, what happened? We were expecting you. Well, my babysitter canceled and I wasn’t able to find a replacement. Oh, that’s too bad. Maybe next time. Well, I really wanted to go. I’m sorry I couldn’t make it. No worries. Some other people couldn’t make it also. Oh, good. I am glad I was not the only one.', '/audio/elllo/B2/B2-03-Was-Able-To/conversation-3-B2-03-3-Was-Able-To-Party.mp3', 1.0),
    (95, 26, 4, 'Before I forget, how was your trip to New York? It was fun. We saw a lot. Did you see the Statue of Liberty? No, we weren’t able to get tickets for the ferry. What about the Empire State Building? I hope you were able to see that. We were able to go there, but we weren’t able to go to the top. Oh no, why not? It was closed for maintenance or something. Oh that’s too bad. Well, I am sure I’ll be able to go back someday!', '/audio/elllo/B2/B2-03-Was-Able-To/conversation-4-B2-03-4-Was-Able-To-Trip.mp3', 1.0),
    (96, 27, 1, 'How was your lunch? Good. I ate at the new taco truck. Really? I was going to go there, but I got busy. How is it? Good, but it is a bit pricey. Oh, really? Yeah, I was going to have two tacos, but at seven bucks apiece, I just had one. Wow, that is pricey!', '/audio/elllo/B2/B2-04-Was-Going-To/conversation-1-B2-04-1-Was-Going-To-Lunch.mp3', 1.0),
    (97, 27, 2, 'Hey, check out my new car! Oh, this is the one that was for sale. Yeah, the guy sold it to us cheap. Really? Is there something wrong with it? No, it is just old. I wasn’t going to buy it at first, but after driving it, I love it. Well, as long as it runs. So, can I get a ride home? I was just going to offer you one.', '/audio/elllo/B2/B2-04-Was-Going-To/conversation-2-B2-04-2-Was-Going-To-Car.mp3', 1.0),
    (98, 27, 3, 'Hey, what a surprise! I was just going to call you. Oh, yeah? What’s up? I was going to ask if you are still coming to the party. Yes, of course. I am really looking forward to it. That’s great. I am so glad you can make it. Are you still planning on having it outside? We were going to, but it looks like it is going to rain. No worries. I prefer indoor parties anyway.', '/audio/elllo/B2/B2-04-Was-Going-To/conversation-3-B2-04-3-Was-Going-To-Call.mp3', 1.0),
    (99, 27, 4, 'Hey, why are you here? I thought you were going to play futsal. I was, but we had to cancel. Oh, yeah? What happened? Bob was going to drive us, but he got called in to work. Oh, he was your only ride? Sadly, yes. Well, now you get to hang out with me! I was just going to say that!', '/audio/elllo/B2/B2-04-Was-Going-To/conversation-4-B2-04-4-Was-Going-To-Game.mp3', 1.0),
    (100, 28, 1, 'Have you ever been to Europe? I haven’t technically been there, but I had a layover in Paris. That doesn’t really count, does it? No, but I''m hopefully going next year. Oh, yeah? Where are you planning on going? I’m tentatively planning on going to Spain. Oh, Spain is definitely worth the visit.', '/audio/elllo/B2/B2-05-Adverb-Placement/conversation-1-B2-05-1-Adverb-Placement-Europe.mp3', 1.0),
    (101, 28, 2, 'What are you doing this weekend? I will probably stay home. What about you? I’m most likely going to stay home too. Oh, yeah? Do you want to do something? No, I''m really looking forward to just relaxing at home. Suit yourself.', '/audio/elllo/B2/B2-05-Adverb-Placement/conversation-2-B2-05-2-Adverb-Placement-Weekend.mp3', 1.0),
    (102, 28, 3, 'Have you tried the new Italian restaurant? No, is it any good? Yes, you should definitely check it out. What do you recommend? Well, I especially recommend the ravioli. It is mouth-watering good. Thanks, I''ll surely give it a look.', '/audio/elllo/B2/B2-05-Adverb-Placement/conversation-3-B2-05-3-Adverb-Placement-Restaurant.mp3', 1.0),
    (103, 28, 4, 'So, did you get the results of your test score? No, but I''ve been anxiously awaiting the results. I''m sure you did fine. I’m not so sure. This test was definitely harder than the last one. I wouldn’t worry about it. I hear all the students eventually pass the class anyway. That’s not true. You’re sadly mistaken.', '/audio/elllo/B2/B2-05-Adverb-Placement/conversation-4-B2-05-4-Adverb-Placement-Test.mp3', 1.0);
